Here is the commit message:
media: mtk-mdp: Fix a refcounting bug on error in init

We need to call of_node_put(comp->dev_node); on the error paths in this
function.

Fixes: c8eb2d7e8202 ("[media] media: Add Mediatek MDP Driver")
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Hans Verkuil <hverkuil-cisco@xs4all.nl>
Signed-off-by: Mauro Carvalho Chehab <mchehab+huawei@kernel.org>

Here is the root cause:
The bug arises from the lack of proper reference counting for the device node in the `mtk_mdp_comp_init` function. When an error occurs during initialization (e.g., failure to obtain a clock or missing device node), the function did not release the reference to `comp->dev_node`, leading to a potential memory leak and incorrect reference counting.

Here is the patch:

 int mtk_mdp_comp_init(struct device *dev, struct device_node *node,
 		      struct mtk_mdp_comp *comp,
 		      enum mtk_mdp_comp_type comp_type)
 {
 	struct device_node *larb_node;
 	struct platform_device *larb_pdev;
+	int ret;
 	int i;

 	comp->dev_node = of_node_get(node);
 	comp->type = comp_type;

 	for (i = 0; i < ARRAY_SIZE(comp->clk); i++) {
 		comp->clk[i] = of_clk_get(node, i);
 		if (IS_ERR(comp->clk[i])) {
 			if (PTR_ERR(comp->clk[i]) != -EPROBE_DEFER)
 				dev_err(dev, "Failed to get clock\n");
-
-			return PTR_ERR(comp->clk[i]);
+			ret = PTR_ERR(comp->clk[i]);
+			goto put_dev;
 		}

 		/* Only RDMA needs two clocks */
 		if (comp->type != MTK_MDP_RDMA)
 			break;
 	}

 	/* Only DMA capable components need the LARB property */
 	comp->larb_dev = NULL;
 	if (comp->type != MTK_MDP_RDMA &&
 	    comp->type != MTK_MDP_WDMA &&
 	    comp->type != MTK_MDP_WROT)
 		return 0;

 	larb_node = of_parse_phandle(node, "mediatek,larb", 0);
 	if (!larb_node) {
 		dev_err(dev,
 			"Missing mediadek,larb phandle in %pOF node\n", node);
-		return -EINVAL;
+		ret = -EINVAL;
+		goto put_dev;
 	}

 	larb_pdev = of_find_device_by_node(larb_node);
 	if (!larb_pdev) {
 		dev_warn(dev, "Waiting for larb device %pOF\n", larb_node);
 		of_node_put(larb_node);
-		return -EPROBE_DEFER;
+		ret = -EPROBE_DEFER;
+		goto put_dev;
 	}
 	of_node_put(larb_node);

 	comp->larb_dev = &larb_pdev->dev;

 	return 0;
+
+put_dev:
+	of_node_put(comp->dev_node);
+
+	return ret;
 }



